function payments(date){let p=panel();back(p,date);heading(p,'🤝 Thu & trả');if(!debtLive(date,today()))p.append(el('p','Khoản nợ ngoài thời hạn thanh toán. Chỉ xem lịch sử.'));p.append(debtInfo());let f=fin[date]||baseFin(),b=balances(f.attendance,f.expenses,f.payments);for(const [id,n] of Object.entries(b)){let r=el('div',undefined,'line');r.append(person(id),el('strong',money(n),n>=0?'positive':'negative'));p.append(r)}if(!Object.keys(f.attendance).length&&!f.expenses.some(e=>e.allocations))p.append(el('p','Chưa chốt người tham gia'));for(const x of f.payments){let r=el('div',undefined,'line');r.append(el('span',`${name(x.from)} → ${name(x.to)} · ${money(x.amount)} · ${x.confirmed?'Đã xác nhận':'Chờ xác nhận'}`));if(!x.group&&debtLive(date,today())&&!x.confirmed&&me()===(x.by===x.from?x.to:x.from))r.append(button('Xác nhận',()=>settleBulk([{...x,date}],true,()=>dayPanel(date,3))));p.append(r)}let debt=Object.keys(b).filter(k=>b[k]<0),credit=Object.keys(b).filter(k=>b[k]>0);if(debtLive(date,today())&&debt.length&&credit.length)form(p,[field('Người trả','select',debt[0],opts(debt)),field('Người nhận','select',credit[0],opts(credit)),field('Số tiền','number','')],'Ghi nhận',async(from,to,amount)=>{amount=Number(amount);if(![from,to].includes(me())||!Number.isSafeInteger(amount)||amount<=0)throw Error('Chỉ ghi giao dịch của mình');await change('finance',date,d=>{let v=balances(d.attendance,d.expenses,d.payments),pending=d.payments.filter(x=>!x.confirmed);if(amount>Math.min(-v[from]-pending.filter(x=>x.from===from).reduce((s,x)=>s+x.amount,0),v[to]-pending.filter(x=>x.to===to).reduce((s,x)=>s+x.amount,0)))throw Error('Vượt số dư');d.payments.push({id:uid(),from,to,amount,by:me(),confirmed:false,at:Date.now()})},`${name(from)} trả ${name(to)} ${money(amount)}`,'payment')});log(p,f.logs.filter(x=>x.kind==='payment'))}
const debtExplanation='Chi phí tháng: Tổng tiền bạn phải chịu trong tháng, kể cả đã thanh toán.\n\nCần thu: Tiền người khác còn nợ bạn.\n\nCần trả: Tiền bạn còn nợ người khác.\n\nCông nợ chỉ tính tháng này và tháng trước. Giao dịch chờ xác nhận vẫn là chưa thanh toán.';
function financeTotals(){let cost=0,receive=0,pay=0;for(const [date,f] of Object.entries(fin)){let b=balances(f.attendance,f.expenses,f.payments)[me()]||0;if(debtLive(date,today())){if(b>0)receive+=b;else pay-=b}if(date.startsWith(month))cost+=monthlyCost(f.attendance,f.expenses,me())}return {cost,receive,pay}}
function debtInfo(){let b=button('ⓘ',()=>notify(debtExplanation));b.className='info-button';b.setAttribute('aria-label','Giải thích công nợ và làm tròn');return b}
