function notesQuery(g){return query(collection(db,'scribbles'),where('generation','==',g),orderBy('at','desc'),limit(20))}
function watchNotes(g){notesStop?.();notesGeneration=g;notes=[];older=[];notesCursor=null;notesMore=false;if(g)notesStop=onSnapshot(notesQuery(g),s=>{if(notesGeneration!==g)return;notes=s.docs.map(d=>({id:d.id,...d.data()}));if(!older.length){notesCursor=s.docs.at(-1);notesMore=s.size===20}boardRender()},boardError);boardRender()}
